//! Post-processing fixups for the OpenAPI spec generated by aide + schemars.
//!
//! schemars 0.9 generates `oneOf` with `const` tag properties for `#[serde(tag = "...")]`
//! enums, but does NOT emit the OpenAPI `discriminator` keyword. This module detects such
//! schemas and injects `discriminator` with `propertyName` and `mapping`.

use aide::openapi::OpenApi;
use serde_json::{Map, Value};

/// Walk all component schemas and inject `discriminator` for oneOf schemas
/// that use a shared const property as a tag (the pattern schemars 0.9 generates
/// for `#[serde(tag = "...")]` enums).
pub fn add_discriminators(api: &mut OpenApi) {
    let components = match api.components.as_mut() {
        Some(c) => c,
        None => return,
    };

    // Collect schema names that need discriminators and their discriminator values.
    // We collect first to avoid borrow issues.
    #[allow(clippy::type_complexity)]
    let fixups: Vec<(String, String, Vec<(String, String)>)> = components
        .schemas
        .iter()
        .filter_map(|(name, schema_obj)| {
            let obj = schema_obj.json_schema.as_object()?;
            detect_discriminator(name, obj)
        })
        .collect();

    for (schema_name, property_name, mapping) in fixups {
        if let Some(schema_obj) = components.schemas.get_mut(&schema_name) {
            let obj = schema_obj.json_schema.as_object_mut().unwrap();
            let mut disc = Map::new();
            disc.insert("propertyName".to_string(), Value::String(property_name));
            let mapping_obj: Map<String, Value> = mapping
                .into_iter()
                .map(|(k, v)| (k, Value::String(v)))
                .collect();
            disc.insert("mapping".to_string(), Value::Object(mapping_obj));
            obj.insert("discriminator".to_string(), Value::Object(disc));
        }
    }
}

/// Detect if a schema object represents a tagged union (oneOf with shared const property).
///
/// Returns `Some((schema_name, property_name, mapping))` if a discriminator should be added.
///
/// The pattern generated by schemars 0.9 for `#[serde(tag = "kind")]` looks like:
///
/// ```json
/// {
///   "oneOf": [
///     {
///       "type": "object",
///       "properties": {
///         "kind": { "const": "markdown" },
///         ...
///       },
///       "required": ["kind", ...]
///     },
///     ...
///   ]
/// }
/// ```
///
/// Or variants may use `allOf` with a `$ref`:
///
/// ```json
/// {
///   "oneOf": [
///     {
///       "allOf": [
///         { "$ref": "#/components/schemas/SomeType" },
///         {
///           "type": "object",
///           "properties": {
///             "kind": { "const": "variant_name" }
///           },
///           "required": ["kind"]
///         }
///       ]
///     },
///     ...
///   ]
/// }
/// ```
#[allow(clippy::type_complexity)]
fn detect_discriminator(
    schema_name: &str,
    obj: &Map<String, Value>,
) -> Option<(String, String, Vec<(String, String)>)> {
    let one_of = obj.get("oneOf")?.as_array()?;
    if one_of.is_empty() {
        return None;
    }

    // Try to find a shared const property name across all variants.
    let mut property_name: Option<String> = None;
    let mut mapping = Vec::new();

    for variant in one_of {
        let variant_obj = variant.as_object()?;

        // Extract the tag property and const value from this variant.
        // Handle both inline objects and allOf patterns.
        let (tag_prop, const_val, ref_name) = extract_tag_info(variant_obj)?;

        // All variants must share the same tag property name.
        match &property_name {
            Some(existing) if existing != &tag_prop => return None,
            None => property_name = Some(tag_prop),
            _ => {}
        }

        // Build the mapping value: prefer $ref if available, otherwise use inline naming.
        let mapping_value = if let Some(ref_path) = ref_name {
            ref_path
        } else {
            // For inline variants, create a reference-style name from the const value.
            // This won't be a real $ref, but it's the conventional mapping format.
            format!("#/components/schemas/{schema_name}/{const_val}")
        };

        mapping.push((const_val, mapping_value));
    }

    let property_name = property_name?;
    if mapping.is_empty() {
        return None;
    }

    Some((schema_name.to_string(), property_name, mapping))
}

/// Extract tag property name, const value, and optional $ref from a oneOf variant.
///
/// Returns `(property_name, const_value, optional_ref_path)`.
fn extract_tag_info(variant: &Map<String, Value>) -> Option<(String, String, Option<String>)> {
    // Case 1: Direct object with properties containing a const tag.
    if let Some(props) = variant.get("properties").and_then(|p| p.as_object())
        && let Some((tag_prop, const_val)) = find_const_property(props)
    {
        return Some((tag_prop, const_val, None));
    }

    // Case 2: allOf combining a $ref with an object that has the const tag.
    if let Some(all_of) = variant.get("allOf").and_then(|a| a.as_array()) {
        let mut ref_path = None;
        let mut tag_info = None;

        for item in all_of {
            let item_obj = item.as_object()?;
            if let Some(r) = item_obj.get("$ref").and_then(|v| v.as_str()) {
                ref_path = Some(r.to_string());
            }
            if let Some(props) = item_obj.get("properties").and_then(|p| p.as_object())
                && let Some((tag_prop, const_val)) = find_const_property(props)
            {
                tag_info = Some((tag_prop, const_val));
            }
        }

        if let Some((tag_prop, const_val)) = tag_info {
            return Some((tag_prop, const_val, ref_path));
        }
    }

    None
}

/// Find a property with a `const` value in a properties map.
///
/// Returns `(property_name, const_value)` for the first property that has a `const` keyword.
fn find_const_property(props: &Map<String, Value>) -> Option<(String, String)> {
    for (prop_name, prop_schema) in props {
        if let Some(prop_obj) = prop_schema.as_object()
            && let Some(const_val) = prop_obj.get("const").and_then(|v| v.as_str())
        {
            return Some((prop_name.clone(), const_val.to_string()));
        }
    }
    None
}

#[cfg(test)]
mod tests {
    use super::*;
    #[allow(unused_imports)]
    use serde_json::json;

    #[test]
    fn test_detect_inline_discriminator() {
        let schema = json!({
            "oneOf": [
                {
                    "type": "object",
                    "properties": {
                        "kind": { "const": "markdown" },
                        "text": { "type": "string" }
                    },
                    "required": ["kind"]
                },
                {
                    "type": "object",
                    "properties": {
                        "kind": { "const": "notice" },
                        "level": { "type": "string" }
                    },
                    "required": ["kind", "level"]
                }
            ]
        });

        let obj = schema.as_object().unwrap();
        let result = detect_discriminator("BriefUnitSubtype", obj);
        assert!(result.is_some());
        let (name, prop, mapping) = result.unwrap();
        assert_eq!(name, "BriefUnitSubtype");
        assert_eq!(prop, "kind");
        assert_eq!(mapping.len(), 2);
        assert!(mapping.iter().any(|(k, _)| k == "markdown"));
        assert!(mapping.iter().any(|(k, _)| k == "notice"));
    }

    #[test]
    fn test_detect_allof_discriminator() {
        let schema = json!({
            "oneOf": [
                {
                    "allOf": [
                        { "$ref": "#/components/schemas/AssetSource" },
                        {
                            "type": "object",
                            "properties": {
                                "type": { "const": "asset" }
                            },
                            "required": ["type"]
                        }
                    ]
                },
                {
                    "allOf": [
                        { "$ref": "#/components/schemas/UrlSource" },
                        {
                            "type": "object",
                            "properties": {
                                "type": { "const": "url" }
                            },
                            "required": ["type"]
                        }
                    ]
                }
            ]
        });

        let obj = schema.as_object().unwrap();
        let result = detect_discriminator("MediaSource", obj);
        assert!(result.is_some());
        let (name, prop, mapping) = result.unwrap();
        assert_eq!(name, "MediaSource");
        assert_eq!(prop, "type");
        assert_eq!(mapping.len(), 2);
        let asset_ref = mapping
            .iter()
            .find(|(k, _)| k == "asset")
            .map(|(_, v)| v.as_str());
        assert_eq!(asset_ref, Some("#/components/schemas/AssetSource"));
        let url_ref = mapping
            .iter()
            .find(|(k, _)| k == "url")
            .map(|(_, v)| v.as_str());
        assert_eq!(url_ref, Some("#/components/schemas/UrlSource"));
    }

    #[test]
    fn test_no_discriminator_for_plain_object() {
        let schema = json!({
            "type": "object",
            "properties": {
                "name": { "type": "string" }
            }
        });

        let obj = schema.as_object().unwrap();
        let result = detect_discriminator("PlainObject", obj);
        assert!(result.is_none());
    }
}
